#include <string.h>

#include "vfs.h"

#define TEST_SUITE_NAME                     "ChibiOS/VFS Test Suite"

#define VFS_TEST_FS_OP_NONE                 0U
#define VFS_TEST_FS_OP_STAT                 1U
#define VFS_TEST_FS_OP_OPENDIR              2U
#define VFS_TEST_FS_OP_OPENFILE             3U
#define VFS_TEST_FS_OP_UNLINK               4U
#define VFS_TEST_FS_OP_RENAME               5U
#define VFS_TEST_FS_OP_MKDIR                6U
#define VFS_TEST_FS_OP_RMDIR                7U

typedef struct {
  const struct vfs_fs_vmt *vmt;
  unsigned                operation;
  unsigned                calls;
  char                    path[VFS_CFG_PATHLEN_MAX + 1];
  char                    newpath[VFS_CFG_PATHLEN_MAX + 1];
  int                     flags;
  vfs_mode_t              mode;
  vfs_stat_t              stat;
  msg_t                   opendir_result;
  msg_t                   openfile_result;
} vfs_test_fs_c;

extern vfs_test_fs_c vfs_test_fs;
extern const vfs_stat_t vfs_test_full_stat;
#if VFS_CFG_ENABLE_DRV_ROOT == TRUE
extern vfs_root_c vfs_test_root;
#endif

bool vfs_test_path_equal(const char *actual, size_t actual_size,
                         const char *expected);
bool vfs_test_path_normalizes(const char *input, const char *expected);
bool vfs_test_path_normalizes_in_place(const char *input,
                                       const char *expected);
bool vfs_test_path_becomes_absolute(const char *cwd, const char *input,
                                    const char *expected);
bool vfs_test_stat_equal(const vfs_stat_t *actual,
                         const vfs_stat_t *expected);
bool vfs_test_stat_optional_is_clear(const vfs_stat_t *sp);
void vfs_test_fs_reset(void);
#if VFS_CFG_ENABLE_DRV_ROOT == TRUE
void vfs_test_root_reset(void);
#endif

global_code.value:
bool vfs_test_path_equal(const char *actual, size_t actual_size,
                         const char *expected) {
  size_t expected_size;

  expected_size = strlen(expected);
  return (actual_size == expected_size) &&
         (memcmp(actual, expected, expected_size + 1U) == 0);
}

bool vfs_test_path_normalizes(const char *input, const char *expected) {
  char buf[128];
  size_t n;

  n = vfs_path_normalize(buf, input, sizeof buf);
  return vfs_test_path_equal(buf, n, expected);
}

bool vfs_test_path_normalizes_in_place(const char *input,
                                       const char *expected) {
  char buf[128];
  size_t n;

  strcpy(buf, input);
  n = vfs_path_normalize(buf, buf, sizeof buf);
  return vfs_test_path_equal(buf, n, expected);
}

bool vfs_test_path_becomes_absolute(const char *cwd, const char *input,
                                    const char *expected) {
  char buf[128];
  size_t n;

  n = vfs_path_make_absolute(buf, input, sizeof buf, cwd);
  return vfs_test_path_equal(buf, n, expected);
}

bool vfs_test_stat_equal(const vfs_stat_t *actual,
                         const vfs_stat_t *expected) {

  return (actual->mode == expected->mode) &&
         (actual->size == expected->size) &&
         (actual->valid == expected->valid) &&
         (actual->blksize == expected->blksize) &&
         (actual->blocks == expected->blocks) &&
         (actual->mtime.tv_sec == expected->mtime.tv_sec) &&
         (actual->mtime.tv_nsec == expected->mtime.tv_nsec);
}

bool vfs_test_stat_optional_is_clear(const vfs_stat_t *sp) {
  static const vfs_stat_t empty = {0};
  vfs_stat_t optional;

  optional = *sp;
  optional.mode = (vfs_mode_t)0;
  optional.size = (vfs_offset_t)0;

  return vfs_test_stat_equal(&optional, &empty);
}

static void vfs_test_fs_dispose(void *ip) {

  (void)ip;
}

static void vfs_test_fs_record(vfs_test_fs_c *self, unsigned operation,
                               const char *path) {

  self->operation = operation;
  self->calls++;
  strcpy(self->path, path);
}

static msg_t vfs_test_fs_stat(void *ip, const char *path, vfs_stat_t *sp) {
  vfs_test_fs_c *self = (vfs_test_fs_c *)ip;

  sp->mode  = self->stat.mode;
  sp->size  = self->stat.size;
  sp->valid = self->stat.valid;
  if ((sp->valid & VFS_STAT_VALID_BLKSIZE) != 0U) {
    sp->blksize = self->stat.blksize;
  }
  if ((sp->valid & VFS_STAT_VALID_BLOCKS) != 0U) {
    sp->blocks = self->stat.blocks;
  }
  if ((sp->valid & VFS_STAT_VALID_MTIME) != 0U) {
    sp->mtime = self->stat.mtime;
  }
  vfs_test_fs_record(self, VFS_TEST_FS_OP_STAT, path);
  return CH_RET_SUCCESS;
}

static msg_t vfs_test_fs_opendir(void *ip, const char *path,
                                 vfs_directory_node_c **vdnpp) {
  vfs_test_fs_c *self = (vfs_test_fs_c *)ip;

  (void)vdnpp;
  vfs_test_fs_record(self, VFS_TEST_FS_OP_OPENDIR, path);
  return self->opendir_result;
}

static msg_t vfs_test_fs_openfile(void *ip, const char *path, int flags,
                                  vfs_file_node_c **vfnpp) {
  vfs_test_fs_c *self = (vfs_test_fs_c *)ip;

  (void)vfnpp;
  vfs_test_fs_record(self, VFS_TEST_FS_OP_OPENFILE, path);
  self->flags = flags;
  return self->openfile_result;
}

static msg_t vfs_test_fs_unlink(void *ip, const char *path) {
  vfs_test_fs_c *self = (vfs_test_fs_c *)ip;

  vfs_test_fs_record(self, VFS_TEST_FS_OP_UNLINK, path);
  return CH_RET_SUCCESS;
}

static msg_t vfs_test_fs_rename(void *ip, const char *oldpath,
                                const char *newpath) {
  vfs_test_fs_c *self = (vfs_test_fs_c *)ip;

  vfs_test_fs_record(self, VFS_TEST_FS_OP_RENAME, oldpath);
  strcpy(self->newpath, newpath);
  return CH_RET_SUCCESS;
}

static msg_t vfs_test_fs_mkdir(void *ip, const char *path, vfs_mode_t mode) {
  vfs_test_fs_c *self = (vfs_test_fs_c *)ip;

  vfs_test_fs_record(self, VFS_TEST_FS_OP_MKDIR, path);
  self->mode = mode;
  return CH_RET_SUCCESS;
}

static msg_t vfs_test_fs_rmdir(void *ip, const char *path) {
  vfs_test_fs_c *self = (vfs_test_fs_c *)ip;

  vfs_test_fs_record(self, VFS_TEST_FS_OP_RMDIR, path);
  return CH_RET_SUCCESS;
}

static const struct vfs_fs_vmt vfs_test_fs_vmt = {
  .dispose  = vfs_test_fs_dispose,
  .stat     = vfs_test_fs_stat,
  .opendir  = vfs_test_fs_opendir,
  .openfile = vfs_test_fs_openfile,
  .unlink   = vfs_test_fs_unlink,
  .rename   = vfs_test_fs_rename,
  .mkdir    = vfs_test_fs_mkdir,
  .rmdir    = vfs_test_fs_rmdir
};

const vfs_stat_t vfs_test_full_stat = {
  .mode          = VFS_MODE_S_IFREG | VFS_MODE_S_IRUSR,
  .size          = (vfs_offset_t)1234,
  .valid         = VFS_STAT_VALID_BLKSIZE |
                   VFS_STAT_VALID_BLOCKS |
                   VFS_STAT_VALID_MTIME,
  .blksize       = (vfs_blksize_t)4096,
  .blocks        = (vfs_blkcnt_t)17,
  .mtime.tv_sec  = (int64_t)1700000000,
  .mtime.tv_nsec = (uint32_t)123456789
};

vfs_test_fs_c vfs_test_fs;
#if VFS_CFG_ENABLE_DRV_ROOT == TRUE
vfs_root_c vfs_test_root;
static char vfs_test_cwd[] = "/home/user";
#endif

void vfs_test_fs_reset(void) {

  (void)__vfsfs_objinit_impl(&vfs_test_fs, &vfs_test_fs_vmt);
  vfs_test_fs.operation       = VFS_TEST_FS_OP_NONE;
  vfs_test_fs.calls           = 0U;
  vfs_test_fs.path[0]         = '\0';
  vfs_test_fs.newpath[0]      = '\0';
  vfs_test_fs.flags           = 0;
  vfs_test_fs.mode            = (vfs_mode_t)0;
  vfs_test_fs.stat            = (vfs_stat_t) {
    .mode = VFS_MODE_S_IFREG,
    .size = (vfs_offset_t)1234
  };
  vfs_test_fs.opendir_result  = CH_RET_SUCCESS;
  vfs_test_fs.openfile_result = CH_RET_SUCCESS;
}

#if VFS_CFG_ENABLE_DRV_ROOT == TRUE
void vfs_test_root_reset(void) {

  vfs_test_fs_reset();
  (void)vfsrootObjectInit(&vfs_test_root, (vfs_fs_c *)&vfs_test_fs, NULL);
  vfs_test_root.path_cwd = vfs_test_cwd;
}
#endif

code.value:
test_assert(vfs_test_path_normalizes(
              "/.hidden/..name/.../normal", "/.hidden/..name/.../normal"),
            "dot-prefixed name normalization failed");

test_assert(vfs_test_path_normalizes_in_place(
              "/a//b/../.hidden", "/a/.hidden"),
            "in-place normalization failed");

test_assert(vfs_test_path_becomes_absolute(
              "/home/user", "../data", "/home/data"),
            "relative parent path resolution failed");

test_assert(vfs_test_path_becomes_absolute(
              "/home/user", "../../../etc", "/etc"),
            "absolute root boundary failed");

test_assert(vfs_test_path_becomes_absolute(
              "/home/user", "/var/./log", "/var/log"),
            "absolute input normalization failed");

local_variables.value:
char buf[16];
char exact[5];
char small[4];
char small_absolute[8];
size_t n;

code.value:
n = vfs_path_normalize(exact, "/abc", sizeof exact);
test_assert(vfs_test_path_equal(exact, n, "/abc"),
            "exact-size buffer rejected");

n = vfs_path_make_absolute(small_absolute, "def",
                           sizeof small_absolute, "/abc");
test_assert(n == (size_t)0, "absolute path overflow accepted");

local_variables.value:
vfs_stat_t stat;
vfs_node_c *np;
vfs_directory_node_c *dnp;
vfs_file_node_c *fnp;
msg_t ret;

code.value:
vfs_test_fs_reset();
memset(&stat, 0xA5, sizeof stat);
ret = vfsFSStat(&vfs_test_fs, "/stat", &stat);
test_assert(ret == CH_RET_SUCCESS, "stat failed");
test_assert(vfs_test_fs.operation == VFS_TEST_FS_OP_STAT,
            "stat dispatch failed");
test_assert(strcmp(vfs_test_fs.path, "/stat") == 0,
            "stat path changed");
test_assert(stat.mode == VFS_MODE_S_IFREG, "stat mode changed");
test_assert(stat.size == (vfs_offset_t)1234, "stat size changed");
test_assert(vfs_test_stat_optional_is_clear(&stat),
            "optional stat metadata not initialized");

vfs_test_fs_reset();
ret = vfsFSOpenDirectory(&vfs_test_fs, "/directory", &dnp);
test_assert(ret == CH_RET_SUCCESS, "directory open failed");
test_assert(vfs_test_fs.operation == VFS_TEST_FS_OP_OPENDIR,
            "directory open dispatch failed");
test_assert(strcmp(vfs_test_fs.path, "/directory") == 0,
            "directory path changed");

vfs_test_fs_reset();
ret = vfsFSOpenFile(&vfs_test_fs, "/file", VO_CREAT | VO_RDWR, &fnp);
test_assert(ret == CH_RET_SUCCESS, "file open failed");
test_assert(vfs_test_fs.operation == VFS_TEST_FS_OP_OPENFILE,
            "file open dispatch failed");
test_assert(strcmp(vfs_test_fs.path, "/file") == 0,
            "file path changed");
test_assert(vfs_test_fs.flags == (VO_CREAT | VO_RDWR),
            "file flags changed");

vfs_test_fs_reset();
ret = vfsFSUnlink(&vfs_test_fs, "/unlink");
test_assert(ret == CH_RET_SUCCESS, "unlink failed");
test_assert(vfs_test_fs.operation == VFS_TEST_FS_OP_UNLINK,
            "unlink dispatch failed");
test_assert(strcmp(vfs_test_fs.path, "/unlink") == 0,
            "unlink path changed");

vfs_test_fs_reset();
ret = vfsFSRename(&vfs_test_fs, "/old", "/new");
test_assert(ret == CH_RET_SUCCESS, "rename failed");
test_assert(vfs_test_fs.operation == VFS_TEST_FS_OP_RENAME,
            "rename dispatch failed");
test_assert(strcmp(vfs_test_fs.path, "/old") == 0,
            "rename old path changed");
test_assert(strcmp(vfs_test_fs.newpath, "/new") == 0,
            "rename new path changed");

vfs_test_fs_reset();
ret = vfsFSMkdir(&vfs_test_fs, "/mkdir", VFS_MODE_S_IRUSR);
test_assert(ret == CH_RET_SUCCESS, "mkdir failed");
test_assert(vfs_test_fs.operation == VFS_TEST_FS_OP_MKDIR,
            "mkdir dispatch failed");
test_assert(strcmp(vfs_test_fs.path, "/mkdir") == 0,
            "mkdir path changed");
test_assert(vfs_test_fs.mode == VFS_MODE_S_IRUSR,
            "mkdir mode changed");

vfs_test_fs_reset();
ret = vfsFSRmdir(&vfs_test_fs, "/rmdir");
test_assert(ret == CH_RET_SUCCESS, "rmdir failed");
test_assert(vfs_test_fs.operation == VFS_TEST_FS_OP_RMDIR,
            "rmdir dispatch failed");
test_assert(strcmp(vfs_test_fs.path, "/rmdir") == 0,
            "rmdir path changed");

vfs_test_fs_reset();
vfs_test_fs.openfile_result = CH_RET_EISDIR;
ret = vfsFSOpen((vfs_fs_c *)&vfs_test_fs, "/node", VO_RDONLY, &np);
test_assert(ret == CH_RET_SUCCESS, "generic directory open failed");
test_assert(vfs_test_fs.operation == VFS_TEST_FS_OP_OPENDIR,
            "generic directory open dispatch failed");
test_assert(vfs_test_fs.calls == 2U, "generic open call count mismatch");
test_assert(strcmp(vfs_test_fs.path, "/node") == 0,
            "generic open path changed");

vfs_test_fs_reset();
vfs_test_fs.openfile_result = CH_RET_EISDIR;
ret = vfsFSOpen((vfs_fs_c *)&vfs_test_fs, "/node", VO_WRONLY, &np);
test_assert(ret == CH_RET_EISDIR, "writable directory open accepted");
test_assert(vfs_test_fs.operation == VFS_TEST_FS_OP_OPENFILE,
            "writable generic open dispatch failed");
test_assert(vfs_test_fs.calls == 1U, "writable generic open fell back");

